/* Page-scoped writing tools. Works in the course and its embedded time lesson. */
(()=>{
 const storeKey='chinese-course-page-annotations-v1';
 function install(w,embedded=false){
  const d=w.document;if(d.querySelector('[data-page-ink-toolbar]'))return;
  const stage=d.querySelector('#stage')||d.querySelector('.stage');const main=d.querySelector('#screen,#deck');const brand=d.querySelector('.brand');if(!main||!brand)return;
  const host=stage||main.parentElement; if(w.getComputedStyle(host).position==='static')host.style.position='relative';
  const style=d.createElement('style');style.textContent=`
.page-ink-toolbar{display:inline-flex;align-items:center;gap:5px;margin-left:12px;flex-shrink:0}.page-ink-toolbar button{font:15px/1.15 'Segoe UI',Arial,sans-serif!important;padding:8px 10px!important;min-height:34px;white-space:nowrap;border:0;border-radius:10px;background:#fffdf7;color:#294638;cursor:pointer}.page-ink-toolbar button[aria-pressed="true"]{background:#557e68;color:white}.page-ink-toolbar button[hidden]{display:none!important}.page-ink-layer{position:absolute;z-index:45;pointer-events:none;overflow:hidden}.page-ink-layer[data-mode="draw"],.page-ink-layer[data-mode="text"]{pointer-events:auto;touch-action:none;cursor:crosshair}.page-ink-layer[data-mode="text"]{cursor:text}.page-ink-svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.page-ink-note{position:absolute;min-width:80px;min-height:42px;width:250px;height:70px;max-width:95%;pointer-events:auto;display:block}.page-ink-note textarea{display:block;box-sizing:border-box;width:100%;height:100%;min-height:0;border:1px dashed transparent;border-radius:6px;resize:none;background:transparent;color:#b16243;font:30px/1.3 'Segoe UI',Arial,sans-serif;padding:3px;box-shadow:none;overflow:auto;touch-action:auto}.page-ink-note textarea:focus{outline:none;border-color:#b16243;background:#fffdf7ed}.page-ink-note button{position:absolute;right:0;top:-20px;background:#fffdf7cc;border:0;border-radius:5px;color:#7d7d6c;padding:2px 6px;font:16px Arial;opacity:0}.page-ink-note:focus-within button,.page-ink-note:hover button{opacity:1}.page-ink-layer[data-mode="draw"] .page-ink-note{pointer-events:none}.brand{min-width:0}.brand>[id="brand"]{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:600px){.page-ink-toolbar{margin-left:4px;gap:3px}.page-ink-toolbar button{font-size:12px!important;padding:7px!important;min-height:32px}.page-ink-note{width:170px}.page-ink-note textarea{font-size:22px}}@media print{.page-ink-toolbar{display:none!important}.page-ink-note button{position:absolute;right:0;top:-20px;display:none}.page-ink-layer{position:absolute}}
.page-ink-resize{position:absolute;right:-4px;bottom:-4px;width:20px;height:20px;border-right:3px solid #b16243;border-bottom:3px solid #b16243;border-radius:0 0 4px 0;cursor:nwse-resize;touch-action:none;background:#fffdf7aa}.page-ink-move{position:absolute;left:0;top:-20px;cursor:move;font:14px Arial;color:#b16243;touch-action:none;padding:2px 10px;background:#fffdf7dd;border-radius:5px}.page-ink-note:focus-within{outline:1px dashed #b16243}.page-ink-note textarea{font-size:inherit}.page-ink-toolbar button[data-mode]{font-weight:600!important;min-width:34px}
`;d.head.append(style);
  const bar=d.createElement('span');bar.className='page-ink-toolbar';bar.dataset.pageInkToolbar='';bar.innerHTML='<button type="button" data-mode="text" aria-pressed="false" aria-label="Добавить текст" title="Добавить текст">T</button><button type="button" data-mode="draw" aria-pressed="false" aria-label="Рисовать" title="Рисовать мышью или пальцем">✎</button><button type="button" data-action="stop" hidden>Готово</button><button type="button" data-action="undo" hidden title="Отменить последнее">↶</button><button type="button" data-action="clear" hidden title="Удалить только пометки этой страницы">Очистить</button>';brand.append(bar);
  const layer=d.createElement('div');layer.className='page-ink-layer';host.append(layer);let mode='',key='',record={strokes:[],notes:[]},active=null;
  const pageKey=()=>{try{if(embedded)return 'time:'+w.eval('index');return w.eval(`typeof group!=='undefined'&&group&&typeof card==='function'&&card()?group+':'+card().id+(card().kind==='vocab'||card().kind==='m3-vocab'?':word:'+wordIndex:''):typeof trainerState!=='undefined'&&location.hash==='#trainer'?'trainer:'+trainerState?.stage+':'+trainerState?.index:location.hash||'#home'`)}catch(e){return w.location.hash||'home'}};
  const save=()=>{try{const all=JSON.parse(w.localStorage.getItem(storeKey)||'{}');if(record.strokes.length||record.notes.length)all[key]=record;else delete all[key];w.localStorage.setItem(storeKey,JSON.stringify(all))}catch(e){}};
  function layout(){const r=main.getBoundingClientRect(),h=host.getBoundingClientRect(),sx=h.width/(host.offsetWidth||h.width),sy=h.height/(host.offsetHeight||h.height);Object.assign(layer.style,{left:(r.left-h.left)/sx+'px',top:(r.top-h.top)/sy+'px',width:r.width/sx+'px',height:r.height/sy+'px'})}
  function setMode(m){mode=m;layer.dataset.mode=m;bar.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===m)));bar.querySelectorAll('[data-action]').forEach(b=>b.hidden=!m)}
  function paint(){layer.replaceChildren();const svg=d.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 1000 1000');svg.setAttribute('preserveAspectRatio','none');svg.classList.add('page-ink-svg');for(const points of record.strokes){const path=d.createElementNS(svg.namespaceURI,'polyline');path.setAttribute('points',points.map(p=>p.join(',')).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke','#b16243');path.setAttribute('stroke-width','3');path.setAttribute('vector-effect','non-scaling-stroke');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');svg.append(path)}layer.append(svg);
   record.notes.forEach((n,i)=>{const box=d.createElement('div');box.className='page-ink-note';box.style.left=n.x+'%';box.style.top=n.y+'%';if(n.w)box.style.width=n.w+'px';box.style.height=(n.h||70)+'px';box.style.fontSize=(n.font||30)+'px';const t=d.createElement('textarea');t.value=n.text;t.setAttribute('aria-label','Пометка на этой странице');t.placeholder='Твой текст';t.addEventListener('input',()=>{n.text=t.value;save()});t.addEventListener('pointerup',()=>{n.w=box.offsetWidth;n.h=box.offsetHeight;save()});const del=d.createElement('button');del.type='button';del.textContent='×';del.title='Удалить пометку';del.onclick=()=>{record.notes.splice(i,1);save();paint()};const handle=d.createElement('span');handle.className='page-ink-resize';handle.title='Потяни за уголок, чтобы изменить размер';handle.setAttribute('role','button');handle.setAttribute('aria-label','Изменить размер текста');const move=d.createElement('span');move.className='page-ink-move';move.textContent='⠿';move.title='Переместить текст';
    function drag(el,resize){let start=null;el.onpointerdown=e=>{e.preventDefault();e.stopPropagation();el.setPointerCapture(e.pointerId);const bounds=layer.getBoundingClientRect();start={x:e.clientX,y:e.clientY,w:box.offsetWidth,h:box.offsetHeight,left:n.x,top:n.y,sx:bounds.width/layer.offsetWidth,sy:bounds.height/layer.offsetHeight}};el.onpointermove=e=>{if(!start)return;e.preventDefault();const dx=(e.clientX-start.x)/start.sx,dy=(e.clientY-start.y)/start.sy;if(resize){n.w=Math.max(80,Math.min(layer.offsetWidth*(1-n.x/100),start.w+dx));n.h=Math.max(42,Math.min(layer.offsetHeight*(1-n.y/100),start.h+dy));n.font=Math.max(14,Math.min(90,30*n.w/250));box.style.width=n.w+'px';box.style.height=n.h+'px';box.style.fontSize=n.font+'px'}else{n.x=Math.max(0,Math.min(90,start.left+dx/layer.offsetWidth*100));n.y=Math.max(3,Math.min(90,start.top+dy/layer.offsetHeight*100));box.style.left=n.x+'%';box.style.top=n.y+'%'}};el.onpointerup=el.onpointercancel=()=>{start=null;save()}}drag(handle,true);drag(move,false);box.append(t,del,handle,move);layer.append(box)})}
  function changePage(){const next=pageKey();if(next===key)return;active=null;key=next;try{record=JSON.parse(w.localStorage.getItem(storeKey)||'{}')[key]||{strokes:[],notes:[]}}catch(e){record={strokes:[],notes:[]}}setMode('');paint();layout()}
  bar.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode==='text'){setMode('text');record.notes.push({x:20,y:25,text:'',w:Math.min(250,layer.offsetWidth*.65),h:70});save();paint();layer.querySelector('.page-ink-note:last-child textarea')?.focus()}else if(b.dataset.mode)setMode(mode===b.dataset.mode?'':b.dataset.mode);else if(b.dataset.action==='stop'){d.activeElement?.blur();setMode('')}else if(b.dataset.action==='undo'){if(record.strokes.length)record.strokes.pop();else record.notes.pop();save();paint()}else if(b.dataset.action==='clear'){record={strokes:[],notes:[]};save();paint()}};
  const point=e=>{const r=layer.getBoundingClientRect();return [Math.max(0,Math.min(1000,(e.clientX-r.left)/r.width*1000)),Math.max(0,Math.min(1000,(e.clientY-r.top)/r.height*1000))]};
  layer.onpointerdown=e=>{if(e.button>0||e.target.closest('.page-ink-note'))return;if(mode==='text'){const p=point(e);record.notes.push({x:Math.min(80,p[0]/10),y:Math.min(90,p[1]/10),text:''});save();paint();layer.querySelector('.page-ink-note:last-child textarea')?.focus();return}if(mode!=='draw')return;e.preventDefault();layer.setPointerCapture(e.pointerId);active=[point(e)];record.strokes.push(active);paint()};
  layer.onpointermove=e=>{if(!active)return;e.preventDefault();active.push(point(e));const path=layer.querySelector('svg polyline:last-child');path?.setAttribute('points',active.map(p=>p.join(',')).join(' '))};layer.onpointerup=layer.onpointercancel=()=>{if(active){active=null;save()}};
  w.addEventListener('resize',layout);w.addEventListener('pagehide',save);w.setInterval(()=>{changePage();layout()},180);changePage();
 }
 install(window);const frame=document.querySelector('#oldFrame');if(frame){const init=()=>{try{install(frame.contentWindow,true)}catch(e){}};frame.addEventListener('load',init);if(frame.contentDocument?.querySelector('#deck'))init()}
})();

